#!/usr/bin/env python3
import json
import os
import re
import urllib.request
from pathlib import Path

REPO = os.environ["GITHUB_REPOSITORY"]
TOKEN = os.environ["GITHUB_TOKEN"]
PATCHES_JSON = Path("patches-list.json")

# Minimum jump required before opening an issue:
# - Always alerts on Major (1.x -> 2.x) or Minor (1.2 -> 1.3) bumps
# - Only alerts on Patch bumps (1.2.1 -> 1.2.6) if the patch number jumps by at least 5
MIN_PATCH_JUMP = 5

def parse_version(v):
    nums = [int(x) for x in re.findall(r"\d+", v)]
    while len(nums) < 3:
        nums.append(0)
    return tuple(nums[:3])

def is_meaningful_update(old_ver, new_ver):
    old_t = parse_version(old_ver)
    new_t = parse_version(new_ver)
    if new_t <= old_t:
        return False
    # Major or Minor version increased (e.g. 1.2.x -> 1.3.0 or 2.0.0)
    if new_t[0] > old_t[0] or new_t[1] > old_t[1]:
        return True
    # Tiny patch bump: only alert if it jumped by MIN_PATCH_JUMP or more
    return (new_t[2] - old_t[2]) >= MIN_PATCH_JUMP

def get_play_version(pkg):
    url = f"https://google.com{pkg}&hl=en_US"
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            html = resp.read().decode("utf-8", "ignore")
        m = re.search(r'\[\[\["(\d+\.\d+(?:\.\d+)*(?:-[a-zA-Z0-9.]+)?)"\]\]', html)
        return m.group(1) if m else None
    except Exception:
        return None

def github_api(path, method="GET", body=None):
    url = f"https://github.com{REPO}{path}"
    data = json.dumps(body).encode("utf-8") if body else None
    req = urllib.request.Request(url, data=data, method=method, headers={
        "Authorization": f"Bearer {TOKEN}",
        "Accept": "application/vnd.github+json",
        "Content-Type": "application/json"
    })
    with urllib.request.urlopen(req) as resp:
        return json.loads(resp.read().decode("utf-8"))

if not PATCHES_JSON.exists():
    print("patches-list.json not found.")
    exit(0)

data = json.loads(PATCHES_JSON.read_text(encoding="utf-8"))
open_issues = github_api("/issues?state=open&per_page=100")

checked = {}
for patch in data.get("patches", []):
    for cp in patch.get("compatiblePackages") or []:
        pkg = cp["packageName"]
        name = cp.get("name") or pkg
        targets = [t["version"] for t in cp.get("targets", []) if t.get("version")]
        if not targets or pkg in checked:
            continue
        latest_supported = sorted(targets, key=parse_version)[-1]
        checked[pkg] = (name, latest_supported)

for pkg, (name, supported_ver) in checked.items():
    play_ver = get_play_version(pkg)
    if not play_ver or not is_meaningful_update(supported_ver, play_ver):
        print(f"Skipping {name}: supported={supported_ver}, play={play_ver}")
        continue

    # Check if ANY open update issue already exists for this package (prevents duplicate issues)
    if any(f"({pkg})" in issue["title"] for issue in open_issues):
        print(f"Open update issue already exists for {name} ({pkg})")
        continue

    issue_title = f"Update {name} ({pkg}) to v{play_ver}"
    print(f"Opening issue: {issue_title}")
    github_api("/issues", method="POST", body={
        "title": issue_title,
        "labels": ["app-update"],
        "body": (
            f"### Meaningful APK Update Detected\n\n"
            f"- **App:** {name}\n"
            f"- **Package:** `{pkg}`\n"
            f"- **Currently Supported:** `{supported_ver}`\n"
            f"- **Latest on Google Play:** `{play_ver}`\n\n"
            f"*Auto-generated by the daily APK version tracker (ignores minor hotfixes).*"
        )
    })
